"""Missing data disclosures generated by code, never by the model."""
import re

SOURCES = {
    "disclosures": ("最新披露", "未能核对最新正式报告与业绩公告，暂不评级"),
    "quote": ("最新报价", "无法建立当前价格依据，暂不评级"),
    "price_validation": ("报告价格校验", "价格依据未通过校验，暂不发布方向性结论"),
    "market": ("行情", "无法核验价格、趋势和技术位"),
    "financials": ("财报", "无法核验财务表现"),
    "news": ("公司新闻", "近期事件和催化剂无法核验"),
    "technical_indicators": ("技术指标", "部分技术判断缺少有效指标支持"),
    "valuation": ("当前估值", "估值分母或股本口径未核验，不能使用旧估值判断便宜或昂贵"),
    "insiders": ("内部人交易", "不能据此断言没有内部人交易"),
    "global_news": ("宏观与政策报道", "已接入来源之外的事件和全球风险覆盖不完整"),
    "macro": ("FRED 宏观指标", "利率、通胀等判断缺少数据验证"),
    "prediction_markets": ("预测市场", "不能提供未经核验的市场隐含概率"),
    "financial_validation": ("财务数值校验", "暂不发布未通过核验的结论"),
}


def reason_text(row):
    if row.get("status") == "not_requested":
        return "本次未查询，数据未知"
    # Strip the transport wrappers ("DATA_UNAVAILABLE: SourceUnavailable: ...")
    # so the source's own explanation is what gets classified and shown.
    reason = re.sub(r"^(?:\s*(?:DATA_UNAVAILABLE|SourceUnavailable|ValueError)\s*:\s*)+", "",
                    str(row.get("reason", "")).strip())
    lower = reason.lower()
    if "未配置" in reason or "not configured" in lower or "not set" in lower:
        return "数据源未配置访问密钥"
    if "timeout" in lower or "timed out" in lower or "超时" in reason:
        return "连接或读取超时"
    if "403" in lower or "cloudflare" in lower:
        return "数据源拒绝访问（HTTP 403 或风控拦截）"
    if "rate limit" in lower or "too many requests" in lower or "429" in lower:
        return "数据源返回限流错误"
    if "httperror" in lower:
        return "接口返回 HTTP 错误，未取得数据"
    if "样本不足" in reason:
        return reason[:180]
    if "withheld" in lower:
        return "该数据源不提供本研究日期的历史数据"
    if "incomplete observed coverage" in lower or "no dated, ticker-matched news" in lower:
        return "没有取得研究时间窗内可核验的相关报道"
    if "fetch failed" in lower or "connection" in lower:
        return "抓取失败，未取得数据"
    if not reason or "unavailable" in lower:
        return "没有取得可核验数据，具体原因未返回"
    return " ".join(reason.split())[:180]


def missing_details(coverage):
    return [{"source": name, "label": SOURCES.get(name, (name, ""))[0],
             "reason": reason_text(row), "impact": SOURCES.get(name, ("", "该部分判断缺少数据支持"))[1]}
            for name, row in coverage.items() if row.get("status") != "available"]


def missing_notice(coverage):
    missing = missing_details(coverage)
    if not missing:
        return ""
    lines = ["## 数据缺口提醒：本次为部分研究", ""]
    for item in missing:
        lines.append(f"- **{item['label']}**：{item['reason']}。影响：{item['impact']}。")
    core = {"market", "quote", "price_validation", "financials", "disclosures", "financial_validation"}
    if any(item["source"] in core for item in missing):
        lines.append("\n**关键数据不足或未通过核验：暂不评级，不生成仓位和价格建议。**")
    else:
        lines.append("\n**以下结论仅基于已取得的资料；上述缺口不能当作中性、没有事件或没有风险。**")
    return "\n".join(lines) + "\n\n"
